UPDATE outfit_plan_item SET image_url = REPLACE(image_url, '.png', '.jpg') WHERE image_url LIKE '/assets/seed/item-%.png';
UPDATE tryon_task_item SET image_url = REPLACE(image_url, '.png', '.jpg') WHERE image_url LIKE '/assets/seed/item-%.png';
UPDATE app_user SET wardrobe_revision = wardrobe_revision + 1 WHERE EXISTS (SELECT 1 FROM wardrobe_item WHERE wardrobe_item.user_id = app_user.id AND wardrobe_item.image_source = 'CATALOG');
